def solve_kalakeya(n, k):
    if k == 0:
        # If K=0, any permutation works, lexicographically smallest is 1,2,3,...,N
        return " ".join(map(str, range(1, n + 1)))

    # Check if we can construct a valid permutation
    # Each position i needs a value with abs(value - i) >= K
    # This means value <= i - K OR value >= i + K

    # We need to greedily assign the smallest available numbers
    used = [False] * (n + 1)
    result = []

    for i in range(1, n + 1):
        found = False
        for val in range(1, n + 1):
            if not used[val] and abs(val - i) >= k:
                result.append(val)
                used[val] = True
                found = True
                break

        if not found:
            return "-1"

    return " ".join(map(str, result))

