                cos_delta = (L_sq + r_sq - D * D) / (2 * L * r)
                cos_delta = max(-1.0, min(1.0, cos_delta))
                delta = math.acos(cos_delta)

                start = phi - delta
                end = phi + delta
                two_pi = 2 * math.pi

                if start < 0:
                    start += two_pi
                if end < 0:
                    end += two_pi
                elif end >= two_pi:
                    end -= two_pi + 1e-9

