                    events.append((two_pi, -1))
                    events.append((0, 1))
                    events.append((end, -1))
                else:
                    events.append((start, 1))
                    events.append((end, -1))

    events.sort()
    max_points = 0
    current = 0

    for angle, delta_count in events:
        current += delta_count
        max_points = max(max_points, current)

    return str(max_points) + "\n"

